// `kreft electron:build` check it and write electron/kreft.resolved.json, which this file reads.
// Add your own code in electron/custom.js (optional): it may export function (app, win, config) { … }.
const { app, BrowserWindow, Menu, Tray, nativeImage, ipcMain, dialog, shell, session, Notification } = require('electron');
const path = require('path');
const http = require('http');
const fs = require('fs');

let C;
try {
  C = JSON.parse(fs.readFileSync(path.join(__dirname, 'kreft.resolved.json'), 'utf8'));
} catch (e) {
  // showErrorBox may be called before the app is ready
  dialog.showErrorBox('Kreft', 'electron/kreft.resolved.json is missing.\nStart the app with "kreft electron:dev" (or build it with "kreft electron:build"): they make this file from config/electron.config.js.');
  app.exit(1);
  process.exit(1);
}

const SELFTEST = !app.isPackaged ? process.env.KREFT_DESKTOP_SELFTEST || '' : '';   // a test hook (never in an installed app): write the real state of the app to this file, then quit
const SELFTEST_MODE = process.env.KREFT_DESKTOP_SELFTEST_MODE || 'development';
const isDev = SELFTEST ? SELFTEST_MODE === 'development' : !app.isPackaged || process.env.NODE_ENV === 'development';
const DEV_PORT = process.env.PORT || 8000;
const DEV_URL = `http://localhost:${DEV_PORT}`;
const devtoolsAllowed = isDev ? C.devtools.development : C.devtools.production;
const isMac = process.platform === 'darwin';

let mainWindow = null;
let tray = null;
let quitting = false;
let menuVisibility = C.menu.visibility;

// ---- the menu --------------------------------------------------------------------------------------------------------

const ROLE = { fullscreen: 'togglefullscreen', selectAll: 'selectAll' };

function toTemplate(items) {
  const out = [];
  for (const it of items || []) {
    if (it.type === 'separator') { out.push({ type: 'separator' }); continue; }
    if (it.role) {
      if (it.role === 'toggleDevTools' && !devtoolsAllowed) continue;
      if (it.role === 'about' && !isMac) continue;
      out.push({ role: ROLE[it.role] || it.role });
      continue;
    }
    const entry = { label: it.label };
    if (it.accelerator) entry.accelerator = it.accelerator;
    if (Array.isArray(it.submenu)) entry.submenu = toTemplate(it.submenu);
    else entry.click = () => { if (mainWindow) mainWindow.webContents.send('kreft:menu', it.id); };
    out.push(entry);
  }
  return out;
}

function applyMenu(visibility) {
  menuVisibility = ['hidden', 'visible', 'auto'].includes(visibility) ? visibility : 'hidden';
  if (menuVisibility === 'hidden') {
    // macOS always has a menu bar. Keep an app menu (Quit) and an Edit menu: without Edit, Cmd+C / Cmd+V stop working.
    Menu.setApplicationMenu(isMac ? Menu.buildFromTemplate([{ role: 'appMenu' }, { role: 'editMenu' }]) : null);
    if (mainWindow && !isMac) { mainWindow.removeMenu(); mainWindow.setMenuBarVisibility(false); mainWindow.setAutoHideMenuBar(false); }
    return;
  }
  const template = C.menu.template ? toTemplate(C.menu.template) : null;
  Menu.setApplicationMenu(template ? Menu.buildFromTemplate(template) : Menu.buildFromTemplate([
    ...(isMac ? [{ role: 'appMenu' }] : []), { role: 'fileMenu' }, { role: 'editMenu' }, { role: 'viewMenu' }, { role: 'windowMenu' },
  ].map((m) => (m.role === 'viewMenu' && !devtoolsAllowed ? { label: 'View', submenu: [{ role: 'togglefullscreen' }, { role: 'resetZoom' }, { role: 'zoomIn' }, { role: 'zoomOut' }] } : m))));
  if (mainWindow && !isMac) {
    mainWindow.setMenu(Menu.getApplicationMenu());
    mainWindow.setAutoHideMenuBar(menuVisibility === 'auto');
    mainWindow.setMenuBarVisibility(menuVisibility === 'visible');
  }
}

// ---- the right-click menu ----------------------------------------------------------------------------------------------

function setupContextMenu(wc) {
  if (!C.contextMenu.enabled) return;
  wc.on('context-menu', (_event, params) => {
    const want = new Set(C.contextMenu.items);
    const items = [];
    const add = (role) => { if (want.has(role)) items.push({ role }); };
    if (params.isEditable) { add('cut'); add('copy'); add('paste'); add('selectAll'); } else if (params.selectionText) add('copy');
    if (devtoolsAllowed && C.contextMenu.inspectElement) {
      if (items.length) items.push({ type: 'separator' });
      items.push({ label: 'Inspect element', click: () => wc.inspectElement(params.x, params.y) });
    }
    if (items.length) Menu.buildFromTemplate(items).popup({ window: mainWindow });
  });
}

// ---- DevTools ---------------------------------------------------------------------------------------------------------

function setupDevTools(wc) {
  if (!devtoolsAllowed) {
    // not allowed: the shortcuts do nothing, and DevTools that open anyway are closed at once
    wc.on('devtools-opened', () => wc.closeDevTools());
    return;
  }
  if (C.devtools.shortcut) {
    wc.on('before-input-event', (event, input) => {
      if (input.type !== 'keyDown') return;
      const key = String(input.key).toLowerCase();
      if (key === 'f12' || (key === 'i' && input.shift && (input.control || (isMac && input.meta && input.alt)))) { wc.toggleDevTools(); event.preventDefault(); }
    });
  }
}

function openDevToolsOnStart(wc) {
  if (devtoolsAllowed && C.devtools.openOnStart) wc.openDevTools({ mode: C.devtools.mode });
}

// ---- security and navigation -------------------------------------------------------------------------------------------

function appOrigins() {
  const list = [...C.webview.allowedNavigation];
  if (isDev) list.push(new URL(DEV_URL).origin);
  return list;
}

function setupSecurity(wc) {
  const origins = appOrigins();
  const dist = path.resolve(__dirname, '..', 'dist');
  wc.setWindowOpenHandler(({ url }) => {
    if (!C.security.blockNewWindows) return { action: 'allow' };
    try {
      const u = new URL(url);
      if ((u.protocol === 'http:' || u.protocol === 'https:') && C.webview.openExternalLinksInBrowser) shell.openExternal(url);
    } catch (_) { /* not an address */ }
    return { action: 'deny' };
  });
  // an address that belongs to the app: its own origins (and the dev server), or a file inside dist/ when packaged
  const isAppUrl = (target) => {
    try {
      const u = new URL(target);
      if (origins.includes(u.origin)) return true;
      if (!isDev && u.protocol === 'file:') {
        const p = path.resolve(decodeURIComponent(u.pathname));
        return p === dist || p.startsWith(dist + path.sep);
      }
    } catch (_) { /* not an address */ }
    return false;
  };
  // redirects and navigations of frames are not 'will-navigate': they are checked here with the same rule
  // (a redirect of the window itself; a frame inside the page, like an embedded video, keeps working as before)
  wc.on('will-redirect', (event, target) => { if (event.isMainFrame !== false && !isAppUrl(target)) event.preventDefault(); });
  wc.on('will-navigate', (event, target) => {
    if (isAppUrl(target)) return;
    event.preventDefault();
    try {
      const u = new URL(target);
      if ((u.protocol === 'http:' || u.protocol === 'https:') && C.webview.openExternalLinksInBrowser) shell.openExternal(target);
    } catch (_) { /* not an address */ }
  });

  const allow = new Set(C.security.permissions);
  if (C.notifications.enabled) allow.add('notifications');
  const ses = session.defaultSession;
  // a permission is granted only when it is allowed AND the page asking is part of the app (not a foreign page or frame)
  // the page that asks: its own address. Only the top page falls back to the window's address (a packaged app has the origin "file://");
  // a frame whose address is unknown is refused, it is not judged by the page that holds it.
  const asker = (web, details, origin) => {
    if (details && details.requestingUrl) return details.requestingUrl;
    if (origin && origin !== 'file://' && origin !== 'null') return origin;
    if (details && details.isMainFrame === false) return '';
    return (web && web.getURL && web.getURL()) || '';
  };
  ses.setPermissionRequestHandler((web, permission, callback, details) => callback(allow.has(permission) && isAppUrl(asker(web, details))));
  ses.setPermissionCheckHandler((web, permission, origin, details) => allow.has(permission) && isAppUrl(asker(web, details, origin)));
  if (C.security.csp) {
    ses.webRequest.onHeadersReceived((details, callback) => {
      callback({ responseHeaders: { ...details.responseHeaders, 'Content-Security-Policy': [C.security.csp] } });
    });
  }
}

// ---- the window --------------------------------------------------------------------------------------------------------

const ICON = path.join(__dirname, '..', C.packaging.icon);

function waitForServer(url, timeout = 15000) {
  const start = Date.now();
  return new Promise((resolve) => {
    const check = () => { http.get(url, (res) => (res.statusCode < 500 ? resolve(true) : retry())).on('error', retry); };
    const retry = () => (Date.now() - start > timeout ? resolve(false) : setTimeout(check, 100));
    check();
  });
}

async function createWindow() {
  const w = C.window;
  const sec = C.security;
  const options = {
    title: w.title,
    useContentSize: true,
    width: w.width,
    height: w.height,
    minWidth: w.minWidth,
    minHeight: w.minHeight,
    resizable: w.resizable,
    fullscreen: w.fullscreen,
    alwaysOnTop: w.alwaysOnTop,
    frame: w.frame,
    transparent: w.transparent,
    backgroundColor: w.transparent ? undefined : w.backgroundColor,
    skipTaskbar: w.skipTaskbar,
    show: !w.showOnReady,
    icon: fs.existsSync(ICON) ? ICON : undefined,
    autoHideMenuBar: menuVisibility === 'auto',
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: sec.contextIsolation,
      sandbox: sec.sandbox,
      nodeIntegration: sec.nodeIntegration,
      webSecurity: sec.webSecurity,
      allowRunningInsecureContent: sec.allowRunningInsecureContent,
      spellcheck: C.webview.spellcheck,
      backgroundThrottling: C.webview.backgroundThrottling,
      devTools: devtoolsAllowed,
      zoomFactor: C.webview.zoomFactor,
    },
  };
  if (w.maxWidth !== null) options.maxWidth = w.maxWidth;
  if (w.maxHeight !== null) options.maxHeight = w.maxHeight;
  if (w.x !== null && w.y !== null) { options.x = w.x; options.y = w.y; } else options.center = w.center;
  if (['light', 'dark'].includes(w.theme)) require('electron').nativeTheme.themeSource = w.theme;

  mainWindow = new BrowserWindow(options);
  const wc = mainWindow.webContents;
  if (C.webview.userAgent) wc.setUserAgent(C.webview.userAgent);

  mainWindow.once('ready-to-show', () => {
    applyMenu(menuVisibility);
    if (w.maximized) mainWindow.maximize();
    mainWindow.show();
  });
  if (!w.showOnReady) applyMenu(menuVisibility);

  setupSecurity(wc);
  setupDevTools(wc);
  setupContextMenu(wc);

  mainWindow.on('close', (event) => {
    if (C.tray.enabled && C.tray.closeToTray && !quitting) { event.preventDefault(); mainWindow.hide(); }
  });
  mainWindow.on('closed', () => { mainWindow = null; });

  if (SELFTEST) {
    await mainWindow.loadURL('data:text/html,<title>kreft</title><p>selftest</p>');
  } else if (isDev) {
    await waitForServer(DEV_URL);
    await mainWindow.loadURL(DEV_URL);
  } else {
    await mainWindow.loadFile(path.join(__dirname, '..', 'dist', 'index.html'));
  }
  openDevToolsOnStart(wc);
  try { require('./custom.js')(app, mainWindow, C); } catch (e) { if (e.code !== 'MODULE_NOT_FOUND') console.error('[kreft] electron/custom.js:', e); }
  if (SELFTEST) setTimeout(writeSelfTest, 400);
}

// ---- the tray ----------------------------------------------------------------------------------------------------------

function showWindow() { if (mainWindow) { mainWindow.show(); mainWindow.focus(); } else createWindow(); }

function setupTray() {
  if (!C.tray.enabled) return;
  const file = path.join(__dirname, '..', C.tray.icon || C.packaging.icon);
  let image = fs.existsSync(file) ? nativeImage.createFromPath(file) : nativeImage.createEmpty();
  if (!image.isEmpty()) image = image.resize({ width: isMac ? 18 : 16, height: isMac ? 18 : 16 });
  tray = new Tray(image);
  tray.setToolTip(C.tray.tooltip);
  const act = {
    show: showWindow,
    hide: () => mainWindow && mainWindow.hide(),
    toggle: () => (mainWindow && mainWindow.isVisible() ? mainWindow.hide() : showWindow()),
    quit: () => app.quit(),
  };
  tray.setContextMenu(Menu.buildFromTemplate(C.tray.menu.map((it) => {
    if (it.type === 'separator') return { type: 'separator' };
    return { label: it.label, click: () => { if (it.action === 'emit') { if (mainWindow) mainWindow.webContents.send('kreft:tray', it.id); } else act[it.action](); } };
  })));
  if (C.tray.clickAction !== 'none') tray.on('click', act[C.tray.clickAction]);
}

// ---- updates -----------------------------------------------------------------------------------------------------------

function setupUpdates() {
  if (!C.updates.enabled || !app.isPackaged) return;
  let autoUpdater;
  try { ({ autoUpdater } = require('electron-updater')); } catch (_) {
    console.warn('[kreft] updates.enabled is on, but "electron-updater" is not installed. Run: kreft add electron-updater');
    return;
  }
  autoUpdater.autoDownload = C.updates.autoDownload;
  autoUpdater.channel = C.updates.channel;
  autoUpdater.setFeedURL({ provider: 'generic', url: C.updates.url, channel: C.updates.channel });
  const tell = (name) => (payload) => { if (mainWindow) mainWindow.webContents.send('kreft:update', { event: name, info: payload && payload.version ? { version: payload.version } : null }); };
  ['update-available', 'update-not-available', 'update-downloaded', 'error'].forEach((n) => autoUpdater.on(n, tell(n)));
  ipcMain.handle('kreft:update:check', () => autoUpdater.checkForUpdates().then(() => true, () => false));
  ipcMain.handle('kreft:update:install', () => autoUpdater.quitAndInstall());
  if (C.updates.checkOnStart) autoUpdater.checkForUpdates().catch(() => {});
}

// ---- the bridge the page can use (see electron/preload.js) ----------------------------------------------------------------

const pickAllowed = (obj, allowed) => {
  const out = {};
  if (!obj || typeof obj !== 'object') return out;
  for (const k of allowed) if (Object.prototype.hasOwnProperty.call(obj, k) && obj[k] !== undefined) out[k] = obj[k];
  return out;
};

ipcMain.handle('kreft:app-info', () => ({ name: app.getName(), version: app.getVersion(), platform: process.platform, arch: process.arch, isPackaged: app.isPackaged }));
ipcMain.handle('kreft:minimize', () => { if (mainWindow) mainWindow.minimize(); });
ipcMain.handle('kreft:maximize', () => { if (mainWindow) (mainWindow.isMaximized() ? mainWindow.unmaximize() : mainWindow.maximize()); });
ipcMain.handle('kreft:close', () => { if (mainWindow) mainWindow.close(); });
ipcMain.handle('kreft:menu', (_e, mode) => { if (mode !== undefined) applyMenu({ show: 'visible', hide: 'hidden' }[mode] || String(mode)); return menuVisibility; });
ipcMain.handle('kreft:devtools:open', (_e, mode) => { if (mainWindow && devtoolsAllowed) mainWindow.webContents.openDevTools({ mode: ['right', 'bottom', 'left', 'detach'].includes(mode) ? mode : C.devtools.mode }); });
ipcMain.handle('kreft:devtools:close', () => { if (mainWindow) mainWindow.webContents.closeDevTools(); });
ipcMain.handle('kreft:devtools:toggle', () => { if (mainWindow && devtoolsAllowed) mainWindow.webContents.toggleDevTools(); });
ipcMain.handle('kreft:notify', (_e, title, body) => {
  if (!C.notifications.enabled || !Notification.isSupported()) return false;
  new Notification({ title: String(title || C.app.name), body: String(body || '') }).show();
  return true;
});
ipcMain.handle('kreft:dialog:message', (_e, o) => dialog.showMessageBox(mainWindow, pickAllowed(o, ['type', 'buttons', 'defaultId', 'title', 'message', 'detail', 'cancelId', 'noLink'])));
ipcMain.handle('kreft:dialog:open', (_e, o) => dialog.showOpenDialog(mainWindow, pickAllowed(o, ['title', 'defaultPath', 'buttonLabel', 'filters', 'properties', 'message'])));
ipcMain.handle('kreft:dialog:save', (_e, o) => dialog.showSaveDialog(mainWindow, pickAllowed(o, ['title', 'defaultPath', 'buttonLabel', 'filters', 'message', 'nameFieldLabel', 'showsTagField'])));

// ---- the test hook: what the app really is, not what the configuration says ------------------------------------------------

function writeSelfTest() {
  const win = mainWindow;
  const menu = Menu.getApplicationMenu();
  const prefs = win.webContents.getLastWebPreferences();
  const [width, height] = win.getContentSize();
  const state = {
    mode: isDev ? 'development' : 'production',
    platform: process.platform,
    appMenu: menu ? menu.items.map((i) => i.label || i.role || '') : null,
    menuBarVisible: process.platform === 'darwin' ? null : win.isMenuBarVisible(),
    autoHideMenuBar: win.isMenuBarAutoHide ? win.isMenuBarAutoHide() : null,
    devToolsAllowed: devtoolsAllowed,
    devToolsOpened: win.webContents.isDevToolsOpened(),
    devToolsPreference: prefs.devTools,
    window: { width, height, resizable: win.isResizable(), fullscreen: win.isFullScreen(), alwaysOnTop: win.isAlwaysOnTop(), minimum: win.getMinimumSize(), title: win.getTitle() },
    webPreferences: { contextIsolation: prefs.contextIsolation, sandbox: prefs.sandbox, nodeIntegration: prefs.nodeIntegration, webSecurity: prefs.webSecurity, allowRunningInsecureContent: prefs.allowRunningInsecureContent },
    tray: Boolean(tray),
    config: { ...C, advanced: undefined },
  };
  // try to open DevTools, as a user would with F12, to see whether they are refused
  win.webContents.toggleDevTools();
  const probeUrl = process.env.KREFT_DESKTOP_SELFTEST_PROBE_URL;   // test hook: ask for a permission from this page too
  const ask = () => Promise.race([
    win.webContents.executeJavaScript("navigator.permissions.query({ name: 'notifications' }).then((r) => r.state)").catch((e) => 'error: ' + e.message),
    new Promise((r) => setTimeout(() => r('timeout'), 4000)),
  ]);
  const probe = async () => {
    state.permissionFromForeignPage = await ask();
    if (probeUrl) { await win.loadURL(probeUrl).catch((e) => { state.probeLoadError = e.message; }); state.permissionFromAppPage = await ask(); }
  };
  probe().then(() => setTimeout(() => {
    state.devToolsOpenedAfterToggle = win.webContents.isDevToolsOpened();
    fs.writeFileSync(SELFTEST, JSON.stringify(state, null, 2));
    app.quit();
  }, 700));
}

// ---- start -------------------------------------------------------------------------------------------------------------

app.whenReady().then(() => {
  if (C.app.name) app.setName(C.app.name);
  applyMenu(menuVisibility);
  createWindow();
  setupTray();
  setupUpdates();
  app.on('activate', () => { if (BrowserWindow.getAllWindows().length === 0) createWindow(); });
});

app.on('before-quit', () => { quitting = true; });
app.on('window-all-closed', () => {
  if (C.tray.enabled && C.tray.closeToTray && !quitting) return;
  if (isDev || process.platform !== 'darwin') app.quit();
});
